package main

import (
	"fmt"
)

const MOD = 1000003

func power(a, b int64) int64 {
	res := int64(1)
	a %= MOD
	for b > 0 {
		if b&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		b >>= 1
	}
	return res
}

func main() {
	var n int64
	fmt.Scan(&n)
	if n == 0 {
		fmt.Println(1)
		return
	}
	fmt.Println(power(3, n-1))
}
